UPDATE results SET statement_tex = 'Let $\psi$ be a primitive character and $0 < \theta < 1$, and suppose that, for arbitrarily large $Y$,
\[ \mathcal G_\psi(x) \le x^\theta \qquad (Y \le x \le Y^{3/2}). \]
Let $A_k(s) = \frac{(-1)^k}{k!}\,\mathcal H_\psi^{(k)}(s)$. If $\sigma$ is large enough, there is a constant $C$ such that, for infinitely many $k$,
\[ |A_k(\sigma + i\tau)| + \Re A_k(\sigma) \le C\,(\sigma - \theta)^{-k} \qquad \text{for all } \tau \in \R. \]', statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 17:10:00', updated_by = 'claude' WHERE id = 123;
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '123', 2, 'no-magic-numbers-2026-11-24', '{"tag":"8JT2","type":"lemma","title":"One-sided bound for the Taylor coefficients","statement_tex":"Let $\\psi$ be a primitive character and $0 < \\theta < 1$, and suppose that, for arbitrarily large $Y$,\n\\[ \\mathcal G_\\psi(x) \\le x^\\theta \\qquad (Y \\le x \\le Y^{3/2}). \\]\nLet $A_k(s) = \\frac{(-1)^k}{k!}\\,\\mathcal H_\\psi^{(k)}(s)$. If $\\sigma$ is large enough, there is a constant $C$ such that, for infinitely many $k$,\n\\[ |A_k(\\sigma + i\\tau)| + \\Re A_k(\\sigma) \\le C\\,(\\sigma - \\theta)^{-k} \\qquad \\text{for all } \\tau \\in \\R. \\]","section_id":104,"position":11,"listed":0,"aliases":["one-sided-taylor-bound"]}', 'claude');
UPDATE proofs SET body_tex = 'Put $g(u) = \mathcal G_\psi(e^u)$ and $K_k(u) = u^k e^{-\sigma u}/k!$. By \ref{8JS3}, $g$ is real with $|g(u)| \le C_\psi e^{2u}$, and differentiating $\mathcal H_\psi(s) = \int_0^\infty g(u)\, e^{-su}\,du$ under the integral gives
\[ A_k(\sigma + i\tau) = \int_0^\infty g(u)\, K_k(u)\, e^{-i\tau u}\,du. \]

\emph{Only an upper bound for $g$ matters.} Since $K_k \ge 0$ and $|g| + g = 2g_+$ with $g_+ = \max(g, 0)$,
\[ |A_k(\sigma + i\tau)| + \Re A_k(\sigma) \le 2\int_0^\infty g_+ K_k. \]

\emph{The kernel is a Gamma density.} For $a < \sigma$,
\[ e^{au} K_k(u) = (\sigma - a)^{-k-1}\, p_{\sigma - a}(u), \qquad p_\beta(u) = \frac{\beta^{k+1} u^k e^{-\beta u}}{k!}, \]
where $p_\beta$ is the density of the Gamma distribution with shape $k+1$ and rate $\beta$. Its mean is $(k+1)/\beta$, and Chernoff''s bound gives, for $0 < \eta < 1$,
\[ \int_{|u - (k+1)/\beta| > \eta (k+1)/\beta} p_\beta(u)\,du \le 2 e^{-c(\eta)\, k}, \qquad c(\eta) = \eta - \log(1+\eta) > 0. \]
So $e^{au} K_k$ has total mass $(\sigma - a)^{-k-1}$, concentrated near $u = k/(\sigma - a)$ with relative width tending to $0$.

\emph{Choice of $k$ and $\sigma$.} Take $Y$ from the hypothesis, $U = \log Y$, and $k = \lceil \frac54 \sigma U \rceil$, so that $k/\sigma$ is the midpoint of the window $W = [U, \frac32 U]$. Fix $\eta > 0$ with $\frac54 (1+\eta)^2 < \frac32$, and take $\sigma$ so large that
\[ \frac{\sigma}{\sigma - 2} < \min\bigl(1 + \eta,\ e^{c(\eta)}\bigr). \]

\emph{Window.} On $W$ we have $g_+(u) \le e^{\theta u}$, so $W$ contributes at most $\int_0^\infty e^{\theta u} K_k = (\sigma - \theta)^{-k-1}$.

\emph{Tails.} Off $W$ we only know $g_+ \le C_\psi e^{2u}$, so we use $a = 2$. The mean $m = (k+1)/(\sigma - 2)$ satisfies $\frac54 U \le m \le \frac54 (1+\eta) U + o(U)$, hence $[(1-\eta)m, (1+\eta)m] \subset W$ for large $U$, and
\[ \int_{u \notin W} g_+ K_k \le 2 C_\psi\, (\sigma - 2)^{-k-1} e^{-c(\eta) k} \le 2 C_\psi\, (\sigma - \theta)^{-k}, \]
since $(\sigma - \theta)/(\sigma - 2) < \sigma/(\sigma - 2) < e^{c(\eta)}$. This is why $\sigma$ must be large: the crude bound $e^{2u}$ moves the mass of the kernel from $k/\sigma$ to $k/(\sigma - 2)$ and multiplies it by $(\sigma/(\sigma-2))^{k+1}$, and both effects must be small compared with the concentration $e^{-c(\eta) k}$.

As $Y \to \infty$ these $k$ are unbounded, which gives the claim with $C = 2 + 4C_\psi$.', body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 17:10:00', updated_by = 'claude' WHERE id = 109;
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '109', 2, 'no-magic-numbers-2026-11-24', '{"result_id":123,"body_tex":"Put $g(u) = \\mathcal G_\\psi(e^u)$ and $K_k(u) = u^k e^{-\\sigma u}/k!$. By \\ref{8JS3}, $g$ is real with $|g(u)| \\le C_\\psi e^{2u}$, and differentiating $\\mathcal H_\\psi(s) = \\int_0^\\infty g(u)\\, e^{-su}\\,du$ under the integral gives\n\\[ A_k(\\sigma + i\\tau) = \\int_0^\\infty g(u)\\, K_k(u)\\, e^{-i\\tau u}\\,du. \\]\n\n\\emph{Only an upper bound for $g$ matters.} Since $K_k \\ge 0$ and $|g| + g = 2g_+$ with $g_+ = \\max(g, 0)$,\n\\[ |A_k(\\sigma + i\\tau)| + \\Re A_k(\\sigma) \\le 2\\int_0^\\infty g_+ K_k. \\]\n\n\\emph{The kernel is a Gamma density.} For $a < \\sigma$,\n\\[ e^{au} K_k(u) = (\\sigma - a)^{-k-1}\\, p_{\\sigma - a}(u), \\qquad p_\\beta(u) = \\frac{\\beta^{k+1} u^k e^{-\\beta u}}{k!}, \\]\nwhere $p_\\beta$ is the density of the Gamma distribution with shape $k+1$ and rate $\\beta$. Its mean is $(k+1)/\\beta$, and Chernoff''s bound gives, for $0 < \\eta < 1$,\n\\[ \\int_{|u - (k+1)/\\beta| > \\eta (k+1)/\\beta} p_\\beta(u)\\,du \\le 2 e^{-c(\\eta)\\, k}, \\qquad c(\\eta) = \\eta - \\log(1+\\eta) > 0. \\]\nSo $e^{au} K_k$ has total mass $(\\sigma - a)^{-k-1}$, concentrated near $u = k/(\\sigma - a)$ with relative width tending to $0$.\n\n\\emph{Choice of $k$ and $\\sigma$.} Take $Y$ from the hypothesis, $U = \\log Y$, and $k = \\lceil \\frac54 \\sigma U \\rceil$, so that $k/\\sigma$ is the midpoint of the window $W = [U, \\frac32 U]$. Fix $\\eta > 0$ with $\\frac54 (1+\\eta)^2 < \\frac32$, and take $\\sigma$ so large that\n\\[ \\frac{\\sigma}{\\sigma - 2} < \\min\\bigl(1 + \\eta,\\ e^{c(\\eta)}\\bigr). \\]\n\n\\emph{Window.} On $W$ we have $g_+(u) \\le e^{\\theta u}$, so $W$ contributes at most $\\int_0^\\infty e^{\\theta u} K_k = (\\sigma - \\theta)^{-k-1}$.\n\n\\emph{Tails.} Off $W$ we only know $g_+ \\le C_\\psi e^{2u}$, so we use $a = 2$. The mean $m = (k+1)/(\\sigma - 2)$ satisfies $\\frac54 U \\le m \\le \\frac54 (1+\\eta) U + o(U)$, hence $[(1-\\eta)m, (1+\\eta)m] \\subset W$ for large $U$, and\n\\[ \\int_{u \\notin W} g_+ K_k \\le 2 C_\\psi\\, (\\sigma - 2)^{-k-1} e^{-c(\\eta) k} \\le 2 C_\\psi\\, (\\sigma - \\theta)^{-k}, \\]\nsince $(\\sigma - \\theta)/(\\sigma - 2) < \\sigma/(\\sigma - 2) < e^{c(\\eta)}$. This is why $\\sigma$ must be large: the crude bound $e^{2u}$ moves the mass of the kernel from $k/\\sigma$ to $k/(\\sigma - 2)$ and multiplies it by $(\\sigma/(\\sigma-2))^{k+1}$, and both effects must be small compared with the concentration $e^{-c(\\eta) k}$.\n\nAs $Y \\to \\infty$ these $k$ are unbounded, which gives the claim with $C = 2 + 4C_\\psi$.","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1}', 'claude');
